var documenterSearchIndex = {"docs":
[{"category":"section","location":"guide/expressions/#Expression-Encoding","page":"Expressions","text":"MORK represents all atoms as byte-encoded expressions stored in the PathMap trie.  Understanding this encoding is useful when working with the low-level ExprZipper API or implementing custom parsers.\n\n","title":"Expression Encoding"},{"category":"section","location":"guide/expressions/#Overview","page":"Expressions","text":"Each expression is encoded as a contiguous byte sequence using a tag–payload scheme.  This allows expressions of arbitrary nesting depth to be stored as flat byte strings and compared structurally using trie operations.","title":"Overview"},{"category":"section","location":"guide/expressions/#Tag-Bytes","page":"Expressions","text":"The first byte of every sub-expression is a tag that indicates its kind:\n\nTag Hex Meaning\nSymbol 0x01 Atom symbol (followed by interned symbol ID)\nVar 0x02 Variable (followed by variable index)\nExpr 0x03 Compound expression (followed by arity, then children)\nInt 0x04 Integer literal\nFloat 0x05 Float literal","title":"Tag Bytes"},{"category":"section","location":"guide/expressions/#Interning","page":"Expressions","text":"Symbol names are interned: each unique string is assigned a compact integer ID, and the ID is stored in the byte sequence rather than the full string.  The mapping is maintained in the global intern table.\n\nusing MORK\n\nid  = intern(\"alice\")         # register or look up \"alice\"\nstr = unintern(id)            # \"alice\"\n\ntbl = interning_table()       # inspect the full table\n\n","title":"Interning"},{"category":"section","location":"guide/expressions/#ExprZipper","page":"Expressions","text":"ExprZipper is a cursor into a byte-encoded expression buffer.  It navigates the structure byte-by-byte, providing access to tags, arities, and payload values.","title":"ExprZipper"},{"category":"section","location":"guide/expressions/#Creating","page":"Expressions","text":"# From a byte buffer\nez = ExprZipper(buffer, start_offset)\n\n# From an s-expression string (parse → encode → zipper)\nexpr_bytes = sexpr_to_bytes(\"(isa alice human)\")\nez = ExprZipper(expr_bytes, 1)","title":"Creating"},{"category":"section","location":"guide/expressions/#Navigation","page":"Expressions","text":"ez_tag(ez)            # current tag byte\nez_arity(ez)          # arity if current node is an Expr\nez_symbol_id(ez)      # symbol ID if current node is a Symbol\nez_var_index(ez)      # variable index if current node is a Var\nez_int_val(ez)        # integer value if current node is Int\nez_float_val(ez)      # float value if current node is Float\n\nez_descend!(ez)       # enter first child of current Expr\nez_next!(ez)          # move to next sibling\nez_at_end(ez)         # true if no more siblings","title":"Navigation"},{"category":"section","location":"guide/expressions/#Building-Expressions","page":"Expressions","text":"buf = UInt8[]\neb  = ExprBuilder(buf)\n\neb_open!(eb)                        # start compound expression\neb_symbol!(eb, intern(\"isa\"))       # add symbol\neb_symbol!(eb, intern(\"alice\"))     # add symbol\neb_symbol!(eb, intern(\"human\"))     # add symbol\neb_close!(eb)                       # close compound → (isa alice human)\n\n","title":"Building Expressions"},{"category":"section","location":"guide/expressions/#Parsing","page":"Expressions","text":"MORK includes multiple frontend parsers, each targeting a different input format:","title":"Parsing"},{"category":"section","location":"guide/expressions/#S-Expression-Parser","page":"Expressions","text":"The default format for humans and most tooling:\n\nexpr = parse_sexpr(\"(isa alice human)\")\ntext = expr_to_sexpr(expr)       # round-trip\n\nSupported syntax:\n\nSymbols: word, kebab-case, snake_case, CamelCase\nVariables: $name\nNumbers: 42, -3.14\nNested: (f (g x) y)\nComments: ;; this is a comment","title":"S-Expression Parser"},{"category":"section","location":"guide/expressions/#HE-Parser-(Hyperon-Encoding)","page":"Expressions","text":"Compact encoding used by upstream MORK for efficient serialization:\n\nexpr = parse_he(he_bytes)","title":"HE Parser (Hyperon Encoding)"},{"category":"section","location":"guide/expressions/#CZ2-/-CZ3-Parsers","page":"Expressions","text":"Columnar-zipper formats optimised for parallel parsing of large corpora:\n\nexpr = parse_cz2(buffer)\nexpr = parse_cz3(buffer)","title":"CZ2 / CZ3 Parsers"},{"category":"section","location":"guide/expressions/#Rosetta-Parser","page":"Expressions","text":"Cross-format translation parser:\n\nexpr = parse_rosetta(text)\n\n","title":"Rosetta Parser"},{"category":"section","location":"guide/expressions/#Conversion-Utilities","page":"Expressions","text":"# Text ↔ expression ↔ bytes\ntext  = \"(isa alice human)\"\nexpr  = sexpr_to_expr(text)         # parse to internal Expr type\nbytes = expr_to_bytes(expr)         # encode to byte sequence\nexpr2 = bytes_to_expr(bytes)        # decode back\ntext2 = expr_to_sexpr(expr2)        # format as s-expression\n\n# Direct text ↔ bytes\nbytes = sexpr_to_bytes(text)\ntext  = bytes_to_sexpr(bytes)\n\n","title":"Conversion Utilities"},{"category":"section","location":"guide/expressions/#Content-Addressing","page":"Expressions","text":"Expressions support content-addressed IDs — a deterministic hash derived from the expression's byte encoding:\n\ncid = content_id(expr_bytes)     # UInt64 content-addressed identifier\n\nTwo structurally identical expressions always produce the same CID, regardless of how or when they were created.  MORK uses CIDs internally to deduplicate atoms.\n\n","title":"Content Addressing"},{"category":"section","location":"guide/expressions/#Performance-Notes","page":"Expressions","text":"Symbol interning means expression comparisons are O(1) for symbols (integer comparison, not string comparison).\nThe byte-encoding layout is chosen to maximise prefix sharing in the PathMap trie — structurally similar expressions share trie prefixes, reducing both storage and query cost.\nExprZipper operates on a raw byte slice with no allocation — suitable for high-frequency inner loops.","title":"Performance Notes"},{"category":"section","location":"guide/zipper_queries/#Direct-Zipper-Algebra-Queries","page":"Zipper Queries","text":"MORK is a rule-driven engine — for most workloads you write rules and let space_metta_calculus! evaluate them.  But for large relational queries over an existing trie (knowledge-graph reachability, prefix-narrowed aggregations, frontier-style graph traversals), the calculus's match → output → rewrite loop is the wrong abstraction.\n\nIn those cases you reach under the calculus and call the underlying PathMap.jl substrate's zipper-algebra primitives directly on space.btm.  This is the same substrate path the calculus uses internally, minus the rule rewriting, output combinators and fixed-point machinery.  It is also the pattern upstream MORK's aunt-kg benchmark uses; the Julia port exposes it identically.\n\n","title":"Direct Zipper-Algebra Queries"},{"category":"section","location":"guide/zipper_queries/#When-to-use-which-layer","page":"Zipper Queries","text":"Workload Use\nGenerates new atoms via rules calculus (space_metta_calculus!)\nMultiple rules whose outputs feed each other calculus\nPer-key aggregations (fsum, fmax, count) calculus (see sinks.md)\nPure reads / traversals over an existing trie direct zipper algebra\nRecursive frontier walks (reachability, transitive closure) direct zipper algebra\nQueries hitting a .act mmap'd snapshot direct zipper algebra\n\nThe two compose: bulk-build via byte-level set_val_at!, query via zipper algebra, then drop into the calculus for any generative step.\n\n","title":"When to use which layer"},{"category":"section","location":"guide/zipper_queries/#The-pattern:-bulk-byte-load-prefix-narrowed-walk","page":"Zipper Queries","text":"The query layer has two pieces.  First, ingest atoms by encoding their byte path directly into the trie — skipping the s-expr parser:\n\nusing MORK\nusing PathMap: read_zipper_at_path, zipper_to_next_val!, zipper_path, set_val_at!\n\n# Encode (rel A B) directly as bytes and insert into space.btm\nfunction bulk_load_pairs!(s::Space, tsv_path::AbstractString) :: Int\n    btm = s.btm\n    sb  = codeunits(\"rel\")\n    buf = UInt8[]\n    n   = 0\n    for line in eachline(tsv_path)\n        a, b = split(line, '\\t')\n        ab = codeunits(a); bb = codeunits(b)\n        empty!(buf)\n        push!(buf, item_byte(ExprArity(UInt8(3))))                  # (_ _ _) arity-3\n        push!(buf, item_byte(ExprSymbol(UInt8(3)))); append!(buf, sb)\n        push!(buf, item_byte(ExprSymbol(UInt8(length(ab))))); append!(buf, ab)\n        push!(buf, item_byte(ExprSymbol(UInt8(length(bb))))); append!(buf, bb)\n        set_val_at!(btm, buf, MORK.UNIT_VAL)\n        n += 1\n    end\n    n\nend\n\nSee expressions.md for the byte-layout invariants the path bytes must satisfy.\n\nSecond, write a query-time prefix and read_zipper_at_path into the subtrie below it.  Iteration via zipper_to_next_val! then walks only that subtrie — O(matching atoms), not O(space):\n\n# Prefix for \"all (rel A *) atoms\"\nfunction rel_prefix(a::AbstractString) :: Vector{UInt8}\n    sb = codeunits(\"rel\"); ab = codeunits(a)\n    buf = UInt8[]\n    push!(buf, item_byte(ExprArity(UInt8(3))))\n    push!(buf, item_byte(ExprSymbol(UInt8(3)))); append!(buf, sb)\n    push!(buf, item_byte(ExprSymbol(UInt8(length(ab))))); append!(buf, ab)\n    buf\nend\n\nfunction neighbors(btm, a::String) :: Vector{String}\n    rz  = read_zipper_at_path(btm, rel_prefix(a))\n    out = String[]\n    while zipper_to_next_val!(rz)\n        rel = collect(zipper_path(rz))\n        tag = byte_item(rel[1])\n        tag isa ExprSymbol || continue\n        push!(out, String(@view rel[2 : 1 + Int(tag.size)]))\n    end\n    out\nend\n\nread_zipper_at_path descends in O(prefix-length) and zipper_to_next_val! is O(1) amortised per emitted value — for sparse relational data, total work is exactly the number of matching atoms.\n\n","title":"The pattern: bulk byte-load + prefix-narrowed walk"},{"category":"section","location":"guide/zipper_queries/#Frontier-iterated-traversal-(reachability)","page":"Zipper Queries","text":"The transitive-closure pattern is a loop of prefix-narrowed walks, one per frontier element:\n\nfunction reach(btm, seeds::Vector{String}) :: Set{String}\n    reached  = Set{String}(seeds)\n    frontier = collect(seeds)\n    while !isempty(frontier)\n        next = String[]\n        for a in frontier, b in neighbors(btm, a)\n            b in reached && continue\n            push!(reached, b); push!(next, b)\n        end\n        frontier = next\n    end\n    reached\nend\n\nEach neighbors(btm, a) costs O(out-degree of a).  Total work is O(|edges-walked|) — every edge is walked at most once because once its source is in reached, it is never re-walked.  This is the standard relational-traversal complexity, achieved at the substrate level without rule-engine overhead.\n\n","title":"Frontier-iterated traversal (reachability)"},{"category":"section","location":"guide/zipper_queries/#Substrate-polymorphism-—-same-code-on-.act-snapshots","page":"Zipper Queries","text":"space.btm (an in-RAM PathMap) and an mmap'd ArenaCompactTree are interchangeable under read_zipper_at_path — see PathMap.jl, guide zippers.md section \"Trie-Format Polymorphism\".\n\nThe entire query module above works unchanged whether you pass it s.btm (in-RAM) or tree = act_open_mmap(\"data.act\") (cold-opened sub-millisecond, ~0 RSS, lazily faulted by the OS):\n\n# Same call shape, different backend\nreach(s.btm,        seeds)   # in-RAM\nreach(act_open_mmap(\"data.act\"), seeds)   # mmap'd .act\n\nSee PathMap's serialization.md section \"Load-Once / Mmap-Forever Workflow\" for the snapshot pattern that makes this practical for large datasets.\n\n","title":"Substrate polymorphism — same code on .act snapshots"},{"category":"section","location":"guide/zipper_queries/#Worked-example-—-full-FAFB-v783-connectome","page":"Zipper Queries","text":"A complete realisation of this pattern lives in packages/Core/examples/connectome/:\n\ninfo_flow_zipper.jl — single-modality reach-flow on the in-RAM trie (3.73 M edges, ~3 min load, then µs-scale per query).\ninfo_flow_all_modalities.jl — all 7 afferent modalities on an mmap'd .act snapshot.  41.7 MB on disk, 0.25 ms cold-open, ~14 s total across all modalities.\n\nBoth files use the same read_zipper_at_path / zipper_to_next_val! core loop documented above, differing only in the backend they open.\n\n","title":"Worked example — full FAFB v783 connectome"},{"category":"section","location":"guide/zipper_queries/#When-to-reach-back-to-the-calculus","page":"Zipper Queries","text":"If a traversal needs:\n\nnew atoms emitted into the space → use rules with (O ...)\nper-key sums / maxes during the walk → use rules with fsum / fmax (see sinks.md)\nper-firing dependency on other rule outputs → use the calculus's priority + fixed-point machinery\n\nDirect zipper algebra is read-only by design.  As soon as your query needs to write into the same space it's reading, the calculus is the right layer — its match → output → fixed-point loop exists precisely to serialise those interactions safely.\n\n","title":"When to reach back to the calculus"},{"category":"section","location":"guide/zipper_queries/#See-also","page":"Zipper Queries","text":"expressions.md — byte-layout your prefixes must match\nsinks.md — aggregation primitives inside the calculus\nspace_rules.md — when to write a rule instead\nPathMap.jl — substrate package\nzippers.md — full zipper API\nserialization.md — .act workflow","title":"See also"},{"category":"section","location":"guide/server/#HTTP-Server-Guide","page":"Server","text":"MORK.jl includes a built-in HTTP server that exposes a MORK space over the network.  It is a 1:1 port of the upstream Rust server/ crate.\n\n","title":"HTTP Server Guide"},{"category":"section","location":"guide/server/#Starting-the-Server","page":"Server","text":"using MORK\n\nresource_dir = \"/tmp/mork-resources\"\nmkpath(resource_dir)\n\nss     = ServerSpace(resource_dir)\nserver = MorkServer(ss, \"0.0.0.0\", 8080, Ref(false), Ref(0))\nprintln(\"MORK server on http://0.0.0.0:8080\")\nserve!(server)    # blocking — use a Task or separate process for non-blocking\n\nOr from the command line:\n\ncd packages/MORK\nMORK_SERVER_PORT=8080 julia --project=. tools/mork_server.jl","title":"Starting the Server"},{"category":"section","location":"guide/server/#Environment-Variables","page":"Server","text":"Variable Default Description\nMORK_SERVER_PORT 8080 Bind port\nMORK_SERVER_ADDR 0.0.0.0 Bind address\nMORK_RESOURCE_DIR /tmp/mork-resources Resource storage directory\n\n","title":"Environment Variables"},{"category":"section","location":"guide/server/#Health-Check","page":"Server","text":"curl http://localhost:8080/status/-\n# {\"status\":\"pathClear\",\"message\":\"\"}\n\n","title":"Health Check"},{"category":"section","location":"guide/server/#Endpoint-Reference","page":"Server","text":"All endpoints accept and return JSON.","title":"Endpoint Reference"},{"category":"section","location":"guide/server/#GET-/status/{path}","page":"Server","text":"Check whether a path in the space is clear (no atoms).\n\ncurl http://localhost:8080/status/my-namespace\n# {\"status\":\"pathClear\",\"message\":\"\"}\n# or\n# {\"status\":\"pathOccupied\",\"message\":\"3 atoms\"}","title":"GET /status/{path}"},{"category":"section","location":"guide/server/#POST-/metta_thread","page":"Server","text":"Execute a metta calculus step.  Runs space_metta_calculus! with the given parameters.\n\ncurl -X POST http://localhost:8080/metta_thread \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"path\": \"computation\", \"max_steps\": 10000}'\n\nResponse:\n\n{\"steps_taken\": 42, \"converged\": true}","title":"POST /metta_thread"},{"category":"section","location":"guide/server/#POST-/metta_thread_suspend","page":"Server","text":"Suspend a running calculus thread.\n\ncurl -X POST http://localhost:8080/metta_thread_suspend \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"path\": \"computation\"}'","title":"POST /metta_thread_suspend"},{"category":"section","location":"guide/server/#POST-/transform","page":"Server","text":"Apply a pattern→template transformation to the space.\n\ncurl -X POST http://localhost:8080/transform \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"pattern\":  \"(input $x)\",\n    \"template\": \"(output $x)\",\n    \"path\":     \"my-namespace\"\n  }'","title":"POST /transform"},{"category":"section","location":"guide/server/#POST-/explore","page":"Server","text":"Query atoms matching a pattern.\n\ncurl -X POST http://localhost:8080/explore \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"pattern\": \"(person $name $age)\", \"path\": \"people\"}'\n\nResponse:\n\n{\n  \"matches\": [\n    {\"$name\": \"alice\", \"$age\": \"30\"},\n    {\"$name\": \"bob\",   \"$age\": \"25\"}\n  ]\n}","title":"POST /explore"},{"category":"section","location":"guide/server/#POST-/import","page":"Server","text":"Import atoms into a namespace from a pattern over the existing space.\n\ncurl -X POST http://localhost:8080/import \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"pattern\":  \"(raw-data $x)\",\n    \"template\": \"(processed $x)\",\n    \"source\":   \"raw\",\n    \"dest\":     \"clean\"\n  }'","title":"POST /import"},{"category":"section","location":"guide/server/#POST-/export","page":"Server","text":"Export atoms from a namespace as a pattern-template mapping.\n\ncurl -X POST http://localhost:8080/export \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"pattern\":  \"(result $x)\",\n    \"template\": \"(archived $x)\",\n    \"source\":   \"results\",\n    \"dest\":     \"archive\"\n  }'","title":"POST /export"},{"category":"section","location":"guide/server/#POST-/copy","page":"Server","text":"Copy a subtrie from one path to another.\n\ncurl -X POST http://localhost:8080/copy \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"from\": \"source-path\", \"to\": \"dest-path\"}'","title":"POST /copy"},{"category":"section","location":"guide/server/#POST-/count","page":"Server","text":"Count atoms matching a pattern.\n\ncurl -X POST http://localhost:8080/count \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"pattern\": \"(person $name $age)\", \"path\": \"people\"}'\n# {\"count\": 3}","title":"POST /count"},{"category":"section","location":"guide/server/#POST-/upload","page":"Server","text":"Upload a resource file to the resource store.\n\ncurl -X POST http://localhost:8080/upload \\\n  -H \"Content-Type: application/octet-stream\" \\\n  --data-binary @my-data.act \\\n  \"http://localhost:8080/upload?name=my-dataset\"","title":"POST /upload"},{"category":"section","location":"guide/server/#GET-/stop","page":"Server","text":"Graceful shutdown.\n\ncurl http://localhost:8080/stop\n\n","title":"GET /stop"},{"category":"section","location":"guide/server/#Status-Streaming","page":"Server","text":"GET /status_stream/{path} returns a Server-Sent Events stream that emits a status event whenever the path changes:\n\ncurl -N http://localhost:8080/status_stream/my-namespace\n\n","title":"Status Streaming"},{"category":"section","location":"guide/server/#Resource-Store","page":"Server","text":"The server maintains a resource store in the configured directory. Resources are persistent ACT (ArenaCompact Trie) files that survive server restarts.\n\n# List available resources\nls /tmp/mork-resources/\n\n# Resources are referenced by name in import/export operations\n\n","title":"Resource Store"},{"category":"section","location":"guide/server/#Julia-Client","page":"Server","text":"MORK.jl includes a Julia client that mirrors the upstream Python client:\n\nusing MORK\n\nclient = MorkClient(\"http://localhost:8080\")\n\n# Status\nclient_status(client, \"my-namespace\")\n\n# Transform\nclient_transform(client,\n    pattern  = \"(raw \\$x)\",\n    template = \"(clean \\$x)\",\n    path     = \"pipeline\")\n\n# Explore\nmatches = client_explore(client, \"(person \\$name \\$age)\", \"people\")","title":"Julia Client"},{"category":"section","location":"guide/sinks/#Sink-Operators","page":"Sinks","text":"A sink is a special output combinator in the O clause of a rule. Instead of simply asserting new atoms, sinks perform stateful aggregation over multiple rule firings.\n\nAll sinks appear as part of the O output combinator:\n\n(exec PRIORITY MATCH (O SINK1 SINK2 ...))\n\n","title":"Sink Operators"},{"category":"section","location":"guide/sinks/#Remove-Sink-—","page":"Sinks","text":"Removes matched atoms from the space.\n\n(- ATOM)\n\nExample — consume source atoms after processing:\n\nspace_add_all_sexpr!(s, \"\"\"\n    (task pending clean-dishes)\n    (task pending write-report)\n\n    ;; Mark tasks as done, removing the pending form\n    (exec 0\n        (, (task pending \\$t))\n        (O (- (task pending \\$t))\n           (+ (task done    \\$t)))\n    )\n\"\"\")\n\nAfter the calculus:\n\n(task pending clean-dishes) — removed\n(task done clean-dishes) — added\n\n","title":"Remove Sink — -"},{"category":"section","location":"guide/sinks/#Add-Sink-—","page":"Sinks","text":"Asserts atoms into the space (explicit form; bare atoms in O also assert).\n\n(+ ATOM)\n\nThe + form is equivalent to a bare atom in the output:\n\n# These two rules are equivalent:\n(exec 0 (, (n \\$x)) (O (+ (result \\$x))))\n(exec 0 (, (n \\$x)) (O    (result \\$x) ))\n\n","title":"Add Sink — +"},{"category":"section","location":"guide/sinks/#Float-Reduction-Sinks","page":"Sinks","text":"These sinks aggregate numeric values across all rule firings, reducing them to a single accumulator atom.","title":"Float Reduction Sinks"},{"category":"section","location":"guide/sinks/#Syntax","page":"Sinks","text":"(fmin (ACCUMULATOR $c) $c VALUE)\n(fmax (ACCUMULATOR $c) $c VALUE)\n(fsum (ACCUMULATOR $c) $c VALUE)\n(fprod (ACCUMULATOR $c) $c VALUE)\n\nSink Operation\nfmin Minimum over all matched values\nfmax Maximum over all matched values\nfsum Sum of all matched values\nfprod Product of all matched values\n\nArguments:\n\n(ACCUMULATOR $c) — atom head for the accumulator; $c is the current value\n$c — variable bound to the current accumulator value\nVALUE — the new value to merge (can be a variable or literal)","title":"Syntax"},{"category":"section","location":"guide/sinks/#Example-—-Temperature-Statistics","page":"Sinks","text":"space_add_all_sexpr!(s, \"\"\"\n    (reading 5.8)\n    (reading 9.6)\n    (reading 5.4)\n    (reading 61.0)\n\n    (exec 0\n        (, (reading \\$x))\n        (O\n            (fmin (stats:min \\$c) \\$c \\$x)\n            (fmax (stats:max \\$c) \\$c \\$x)\n            (fsum (stats:sum \\$c) \\$c \\$x)\n        )\n    )\n\n    ;; Remove source atoms after aggregation\n    (exec 1\n        (, (reading \\$x))\n        (O (- (reading \\$x)))\n    )\n\"\"\")\n\nspace_metta_calculus!(s, 100_000)\nprintln(space_dump_all_sexpr(s))\n# => (stats:min 5.4)\n# => (stats:max 61.0)\n# => (stats:sum 81.8)","title":"Example — Temperature Statistics"},{"category":"section","location":"guide/sinks/#Notes","page":"Sinks","text":"The accumulator variable $c is unified with the current accumulator value on each firing.  The sink updates the atom in-place.\nMultiple float reduction sinks can appear in a single O clause, each maintaining its own accumulator.\nThe product of {5.8, 9.6, 5.4, 61.0} ≈ 18340.99.\n\n","title":"Notes"},{"category":"section","location":"guide/sinks/#Count-Sink","page":"Sinks","text":"Counts the number of times a pattern fires.\n\n(count (COUNTER $c) $c)\n\nExample:\n\nspace_add_all_sexpr!(s, \"\"\"\n    (item a)\n    (item b)\n    (item c)\n\n    (exec 0\n        (, (item \\$x))\n        (O (count (total \\$c) \\$c))\n    )\n\"\"\")\n\nspace_metta_calculus!(s, 10_000)\n# => (total 3)\n\n","title":"Count Sink"},{"category":"section","location":"guide/sinks/#Bipolar-Sinks","page":"Sinks","text":"Bipolar sinks manage positive and negative evidence separately, supporting paraconsistent reasoning.\n\n(+ (positive ATOM))   ;; assert positive evidence\n(- (negative ATOM))   ;; retract negative evidence\n\nExample — evidence aggregation:\n\nspace_add_all_sexpr!(s, \"\"\"\n    (evidence positive alice trustworthy)\n    (evidence positive alice trustworthy)\n    (evidence negative alice trustworthy)\n\n    (exec 0\n        (, (evidence positive \\$x \\$prop))\n        (O (+ (supports \\$x \\$prop)))\n    )\n\n    (exec 0\n        (, (evidence negative \\$x \\$prop))\n        (O (- (contradicts \\$x \\$prop)))\n    )\n\"\"\")\n\n","title":"Bipolar Sinks"},{"category":"section","location":"guide/sinks/#Combining-Sinks","page":"Sinks","text":"Multiple sinks can appear in a single O clause.  They all operate on the same matched variable bindings:\n\nspace_add_all_sexpr!(s, \"\"\"\n    (measurement 10.0)\n    (measurement 20.0)\n    (measurement 30.0)\n\n    (exec 0\n        (, (measurement \\$x))\n        (O\n            (fsum  (total \\$c)   \\$c \\$x)   ;; accumulate sum\n            (fmax  (peak  \\$c)   \\$c \\$x)   ;; track maximum\n            (count (n     \\$c)   \\$c)        ;; count firings\n            (- (measurement \\$x))            ;; consume source\n        )\n    )\n\"\"\")\n\nspace_metta_calculus!(s, 10_000)\n# => (total 60.0)\n# => (peak 30.0)\n# => (n 3)\n\n","title":"Combining Sinks"},{"category":"section","location":"guide/sinks/#Sink-Implementation-Notes","page":"Sinks","text":"Sinks are implemented in src/kernel/Sinks.jl and resolve during space_metta_calculus!.  Each sink maintains state in the space itself as accumulator atoms — there is no separate sink state outside the space.\n\nThis means:\n\nAccumulator atoms are visible in space_dump_all_sexpr at any time\nSnapshots capture sink state automatically\nRules can match on accumulator atoms to trigger further computation","title":"Sink Implementation Notes"},{"category":"section","location":"#MORK.jl","page":"Home","text":"A Julia implementation of the MORK metagraph rewriting engine — the high-performance, trie-native substrate for symbolic computation, built on PathMap.jl.\n\nMORK is an independent Julia port of the Rust MORK kernel, hardened by a deep Rust→Julia porting audit (intern races, numeric-primitive width, COW discipline, operator-precedence transpilation defects).","title":"MORK.jl"},{"category":"section","location":"#Features","page":"Home","text":"Expression engine — byte-encoded s-expressions over a PathMap{UnitVal} substrate, with prefix-scoped multi-space queries.\nTransform / exec — pattern→template rewriting, sinks (Count/Head/AU/…), and the metta-calculus step.\nConcurrent symbol interning — thread-safe bucket-map symbol table.\nNumeric primitives — full u8…u128 / i8…i128 / f32 / f64 op suite.","title":"Features"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(url=\"https://github.com/CognitiveSubstratesAI/MORK\")","title":"Installation"},{"category":"section","location":"#Contents","page":"Home","text":"Pages = [\n    \"guide/expressions.md\",\n    \"guide/zipper_queries.md\",\n    \"guide/space_rules.md\",\n    \"guide/sinks.md\",\n    \"guide/server.md\",\n]\nDepth = 1","title":"Contents"},{"category":"section","location":"guide/space_rules/#Space-and-Rules-Guide","page":"Space Rules","text":"A Space is MORK's central computation unit — a mutable collection of atoms (s-expressions) together with rewrite rules that drive computation.\n\n","title":"Space & Rules Guide"},{"category":"section","location":"guide/space_rules/#Creating-and-Populating-a-Space","page":"Space Rules","text":"using MORK\n\ns = new_space()\n\n# Add atoms from multi-line s-expression text\nspace_add_all_sexpr!(s, \"\"\"\n    (person alice 30)\n    (person bob   25)\n    (person carol 35)\n\"\"\")\n\n# Add a single atom\nspace_add_sexpr!(s, \"(person dave 28)\")\n\nAll atoms are immediately indexed.  Duplicate insertion is idempotent.\n\n","title":"Creating and Populating a Space"},{"category":"section","location":"guide/space_rules/#Atom-Format-—-S-Expressions","page":"Space Rules","text":"MORK atoms are s-expressions: symbols, variables, and nested expressions.\n\nSyntax Meaning Example\nword Symbol alice, isa, +\n$name Variable (in patterns) $x, $person\n42, 3.14 Numeric literals 42, 3.14\n(f a b) Compound expression (isa alice human)\n\n","title":"Atom Format — S-Expressions"},{"category":"section","location":"guide/space_rules/#Writing-Rules","page":"Space Rules","text":"Rules are atoms with the special exec head:\n\n(exec PRIORITY MATCH OUTPUT)\n\nField Description\nPRIORITY Integer or tuple — rules fire in ascending order\nMATCH , (comma) combinator listing source patterns\nOUTPUT O combinator listing output atoms or sink operations","title":"Writing Rules"},{"category":"section","location":"guide/space_rules/#Simple-Rule","page":"Space Rules","text":"space_add_all_sexpr!(s, \"\"\"\n    ;; For every person atom, create a greeting\n    (exec 0\n        (, (person \\$name \\$age))\n        (O (greeting \\$name))\n    )\n\"\"\")","title":"Simple Rule"},{"category":"section","location":"guide/space_rules/#Multi-Pattern-Match","page":"Space Rules","text":"The , combinator requires all patterns to match simultaneously (conjunction over the space).  Variables are unified across patterns:\n\nspace_add_all_sexpr!(s, \"\"\"\n    ;; Find siblings: same parent, different child\n    (exec 0\n        (, (parent \\$p \\$a) (parent \\$p \\$b))\n        (O (siblings \\$a \\$b))\n    )\n\"\"\")","title":"Multi-Pattern Match"},{"category":"section","location":"guide/space_rules/#Multiple-Outputs","page":"Space Rules","text":"space_add_all_sexpr!(s, \"\"\"\n    (exec 0\n        (, (temperature \\$t))\n        (O\n            (celsius    \\$t)                ;; keep original\n            (fahrenheit (* \\$t 1.8) + 32)  ;; add derived fact\n        )\n    )\n\"\"\")\n\n","title":"Multiple Outputs"},{"category":"section","location":"guide/space_rules/#Running-the-Calculus","page":"Space Rules","text":"max_steps = 100_000\nsteps = space_metta_calculus!(s, max_steps)\n\nif steps < max_steps\n    println(\"Converged in $steps steps\")\nelse\n    println(\"Hit step cap — may not be at fixed point\")\nend\n\nThe calculus repeatedly applies all enabled rules until no rule fires (fixed point) or the step cap is reached.\n\nStep cap guidance: For small examples, 1_000 is sufficient. For production spaces with many rules, 100_000 or more may be needed. Never use typemax(Int) — always set an explicit cap.\n\n","title":"Running the Calculus"},{"category":"section","location":"guide/space_rules/#Querying-the-Space","page":"Space Rules","text":"# Check atom existence\nspace_has_sexpr(s, \"(greeting alice)\")   # true/false\n\n# Count atoms\nspace_atom_count(s)\n\n# Dump all atoms (for debugging)\nprintln(space_dump_all_sexpr(s))\n\n# Pattern query — returns list of binding sets\nbindings = space_query_sexpr(s, \"(greeting \\$name)\")\nfor b in bindings\n    println(b)   # Dict{Symbol, Expr} of variable → value\nend","title":"Querying the Space"},{"category":"section","location":"guide/space_rules/#Multi-Pattern-Query","page":"Space Rules","text":"results = space_query_multi_i(s, [\n    \"(person \\$x \\$age)\",\n    \"(greeting \\$x)\"\n])\n\n","title":"Multi-Pattern Query"},{"category":"section","location":"guide/space_rules/#Rule-Priority","page":"Space Rules","text":"Rules fire in ascending priority order.  Lower priority numbers fire first.  When multiple rules have the same priority, they all fire in the same pass.\n\nspace_add_all_sexpr!(s, \"\"\"\n    ;; Phase 1: collect data\n    (exec 0 (, (raw \\$x))    (O (processed \\$x)))\n    ;; Phase 2: aggregate (fires after phase 1 has stabilised)\n    (exec 1 (, (processed \\$x)) (O (done \\$x)))\n\"\"\")\n\nFor fine-grained ordering within a priority level, use tuple priorities:\n\n# (1) fires before (2) which fires before (3)\n(exec (0 1) ...)\n(exec (0 2) ...)\n(exec (0 3) ...)\n\n","title":"Rule Priority"},{"category":"section","location":"guide/space_rules/#Space-Snapshots","page":"Space Rules","text":"Save and restore space state:\n\nsnapshot = space_backup(s)\nspace_metta_calculus!(s, 10_000)\n# If results are undesirable:\nspace_restore!(s, snapshot)\n\n","title":"Space Snapshots"},{"category":"section","location":"guide/space_rules/#Complete-Example-—-Transitive-Closure","page":"Space Rules","text":"s = new_space()\nspace_add_all_sexpr!(s, \"\"\"\n    (edge a b)\n    (edge b c)\n    (edge c d)\n\n    ;; Direct edges are reachable\n    (exec 0\n        (, (edge \\$x \\$y))\n        (O (reachable \\$x \\$y))\n    )\n\n    ;; Transitive: if x reaches y and y reaches z, then x reaches z\n    (exec 1\n        (, (reachable \\$x \\$y) (reachable \\$y \\$z))\n        (O (reachable \\$x \\$z))\n    )\n\"\"\")\n\nspace_metta_calculus!(s, 10_000)\nprintln(space_dump_all_sexpr(s))\n# => (reachable a b), (reachable a c), (reachable a d),\n#    (reachable b c), (reachable b d), (reachable c d), ...","title":"Complete Example — Transitive Closure"},{"category":"section","location":"api/README/#MORK-API-Reference","page":"API Reference","text":"Complete index of exported symbols from MORK.jl.\n\nFor prose guides see docs/guide/:\n\nexpressions.md — byte-encoding layout\nspace_rules.md — writing rules + the calculus\nsinks.md — output combinators (+, -, fsum, count, ...)\nserver.md — HTTP server surface\nzipper_queries.md — direct PathMap zipper-algebra queries (use when you want reads / traversals over an existing trie without the rule engine; works polymorphically over .act mmap'd snapshots)\n\nThe trie substrate lives in a separate package: PathMap.jl — byte-keyed, prefix-compressed, structurally-shared trie with first-class zipper algebra and .act mmap serialization.  See its docs/guide/ for the substrate API.\n\n","title":"MORK API Reference"},{"category":"section","location":"api/README/#Space-—-Core-Container","page":"API Reference","text":"Symbol Description\nnew_space() Create a new empty Space\nspace_add_sexpr!(s, text) Add one atom from s-expr text\nspace_add_all_sexpr!(s, text) Add multiple atoms from s-expr text\nspace_has_sexpr(s, text) True if atom exists\nspace_remove_sexpr!(s, text) Remove an atom\nspace_dump_all_sexpr(s) Return all atoms as s-expr string\nspace_atom_count(s) Number of atoms in space\nspace_metta_calculus!(s, max_steps) Run calculus to fixed point\nspace_query_sexpr(s, pattern) Match a pattern, return bindings\nspace_query_multi_i(s, patterns) Multi-pattern query\nspace_backup(s) Snapshot the space\nspace_restore!(s, snapshot) Restore a snapshot\n\n","title":"Space — Core Container"},{"category":"section","location":"api/README/#Expression-Encoding","page":"API Reference","text":"Symbol Description\nexpr_to_bytes(expr) Encode expression to bytes\nbytes_to_expr(bytes) Decode bytes to expression\nsexpr_to_expr(text) Parse s-expr text to expression\nexpr_to_sexpr(expr) Format expression as s-expr text\nExprZipper Cursor into a byte-encoded expression\nez_* functions ExprZipper navigation and mutation\n\n","title":"Expression Encoding"},{"category":"section","location":"api/README/#Sinks","page":"API Reference","text":"Symbol Description\nRemoveSink - operator — removes matched atoms\nAddSink + operator — asserts atoms\nFloatReductionSink fmin/fmax/fsum/fprod aggregators\nCountSink Counting sink\nBipolarSink Dual +/- sink\n\n","title":"Sinks"},{"category":"section","location":"api/README/#Sources","page":"API Reference","text":"Symbol Description\nCmpSource Comparison source (deferred)\nspace_query_multi_i Multi-source query driver\n\n","title":"Sources"},{"category":"section","location":"api/README/#HTTP-Server","page":"API Reference","text":"Symbol Description\nServerSpace(dir) Create a server-backed space\nMorkServer(ss, addr, port, ...) Create HTTP server\nserve!(server) Start serving (blocking)\n\n","title":"HTTP Server"},{"category":"section","location":"api/README/#Parsers","page":"API Reference","text":"Symbol Description\nparse_sexpr(text) S-expression parser\nparse_he(text) HE (Hyperon Encoding) parser\nparse_cz2(text) CZ2 parser\nparse_cz3(text) CZ3 parser\nparse_rosetta(text) Rosetta parser\n\n","title":"Parsers"},{"category":"section","location":"api/README/#Utilities","page":"API Reference","text":"Symbol Description\nversion() Package version\nMorkL MorkL interpreter module\ninterning_table() Global symbol intern table","title":"Utilities"}]
}
